29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
40	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
41	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
42	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
43	import org.springframework.samples.petclinic.rest.api.OwnersApi;
44	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
45	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.PetDto;
47	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Matches a syntactically valid email: a non-empty local part and domain separated by a single
70	     * '@', with at least one dot-separated label in the domain and no whitespace anywhere.
71	     */
72	    private static final Pattern EMAIL_PATTERN =
73	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        validateRequiredFields(ownerFieldsDto);
122	        HttpHeaders headers = new HttpHeaders();
123	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
124	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
125	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
126	        rejectDuplicateTelephone(telephone);
127	        owner.setTelephone(telephone);
128	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
129	        if (owner.getRegistrationDate() == null) {
130	            owner.setRegistrationDate(LocalDate.now());
131	        }
132	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
133	        this.clinicService.saveOwner(owner);
134	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
135	        headers.setLocation(UriComponentsBuilder.newInstance()
136	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
137	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
138	    }
139	
140	    /**
141	     * Builds the next customer code, formatted {@code <LAST3>-<NNNN>} where LAST3 is the
142	     * upper-cased first three letters of the owner's last name and NNNN is a global 4-digit
143	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
144	     *
145	     * @param lastName the owner's last name
146	     * @return the assigned customer code
147	     */
148	    private String nextCustomerCode(String lastName) {
149	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
150	        int sequence = this.clinicService.findAllOwners().size() + 1;
151	        return String.format("%s-%04d", last3, sequence);
152	    }
153	
154	    /**
155	     * Rejects an owner whose required fields are missing or blank. Collects the names of every
156	     * offending field so the client learns about all of them at once.
157	     *
158	     * @param ownerFieldsDto the submitted owner fields
159	     * @throws MissingOwnerFieldsException if firstName, lastName, address, city or telephone is
160	     *                                     missing or blank
161	     */
162	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
163	        List<String> errors = new ArrayList<>();
164	        if (isBlank(ownerFieldsDto.getFirstName())) {
165	            errors.add("firstName");
166	        }
167	        if (isBlank(ownerFieldsDto.getLastName())) {
168	            errors.add("lastName");
169	        }
170	        if (isBlank(ownerFieldsDto.getAddress())) {
171	            errors.add("address");
172	        }
173	        if (isBlank(ownerFieldsDto.getCity())) {
174	            errors.add("city");
175	        }
176	        if (isBlank(ownerFieldsDto.getTelephone())) {
177	            errors.add("telephone");
178	        }
179	        if (!errors.isEmpty()) {
180	            throw new MissingOwnerFieldsException(errors);
181	        }
182	    }
183	
184	    private boolean isBlank(String value) {
185	        return value == null || value.isBlank();
186	    }
187	
188	    /**
189	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
190	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
191	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
192	     * followed by 8 to 15 digits.
193	     *
194	     * @param telephone the raw telephone value as submitted
195	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
196	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
197	     */
198	    private String normalizeTelephone(String telephone) {
199	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
200	        String nationalSignificantNumber;
201	        if (cleaned.startsWith("+")) {
202	            nationalSignificantNumber = cleaned.substring(1);
203	        } else {
204	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
205	            nationalSignificantNumber = "61" + national;
206	        }
207	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
208	            throw new InvalidTelephoneException(telephone);
209	        }
210	        return "+" + nationalSignificantNumber;
211	    }
212	
213	    /**
214	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
215	     * value is treated as absent and returns {@code null}); when present the value must be a
216	     * syntactically valid address, and is stored and returned lower-cased.
217	     *
218	     * @param email the raw email value as submitted, may be {@code null}
219	     * @return the lower-cased email, or {@code null} when none was supplied
220	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
221	     */
222	    private String normalizeEmail(String email) {
223	        if (email == null || email.isBlank()) {
224	            return null;
225	        }
226	        String normalized = email.trim().toLowerCase();
227	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
228	            throw new InvalidEmailException(email);
229	        }
230	        return normalized;
231	    }
232	
233	    /**
234	     * Rejects a normalized telephone that is already used by any other owner, so telephones stay
235	     * unique across owners. Existing telephones are normalized to E.164 the same way before the
236	     * comparison, so numbers that differ only in formatting still count as duplicates.
237	     *
238	     * @param e164Telephone the E.164 telephone of the owner being created
239	     * @throws DuplicateTelephoneException if another owner already uses the same E.164 telephone
240	     */
241	    private void rejectDuplicateTelephone(String e164Telephone) {
242	        boolean inUse = this.clinicService.findAllOwners().stream()
243	            .map(Owner::getTelephone)
244	            .filter(existing -> existing != null)
245	            .map(this::toComparableTelephone)
246	            .filter(existing -> existing != null)
247	            .anyMatch(e164Telephone::equals);
248	        if (inUse) {
249	            throw new DuplicateTelephoneException(e164Telephone);
250	        }
251	    }
252	
253	    /**
254	     * Normalizes an existing owner's stored telephone to E.164 for duplicate comparison, returning
255	     * {@code null} when it cannot be normalized so a malformed legacy value is simply skipped rather
256	     * than aborting the whole create.
257	     */
258	    private String toComparableTelephone(String telephone) {
259	        try {
260	            return normalizeTelephone(telephone);
261	        } catch (InvalidTelephoneException ex) {
262	            return null;
263	        }
264	    }
265	
266	    /**
267	     * Applies the household rule to an owner being created. An owner belongs to the same household
268	     * as an existing owner when their lastName and address both match (compared case-insensitively
269	     * with runs of whitespace collapsed to a single space).
270	     *
271	     * <p>When no such existing owner exists there is nothing to do. Otherwise the request must
272	     * deliberately opt in to sharing that household by setting {@code sharesHousehold=true}: when it
273	     * does, the new owner and every existing owner in the household are assigned the same stable
274	     * {@link #householdId(String, String) householdId}; when it does not, the create is rejected.
275	     *
276	     * @param owner            the owner being created
277	     * @param sharesHousehold  the request's {@code sharesHousehold} flag, may be {@code null}
278	     * @throws DuplicateHouseholdException if another owner shares the same lastName and address and
279	     *                                     the request did not opt in with {@code sharesHousehold=true}
280	     */
281	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
282	        String lastNameKey = toHouseholdKey(owner.getLastName());
283	        String addressKey = toHouseholdKey(owner.getAddress());
284	        List<Owner> household = this.clinicService.findAllOwners().stream()
285	            .filter(existing -> toHouseholdKey(existing.getLastName()).equals(lastNameKey)
286	                && toHouseholdKey(existing.getAddress()).equals(addressKey))
287	            .toList();
288	        if (household.isEmpty()) {
289	            return;
290	        }
291	        if (!Boolean.TRUE.equals(sharesHousehold)) {
292	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
293	        }
294	        String householdId = householdId(lastNameKey, addressKey);
295	        owner.setHouseholdId(householdId);
296	        for (Owner existing : household) {
297	            if (!householdId.equals(existing.getHouseholdId())) {
298	                existing.setHouseholdId(householdId);
299	                this.clinicService.saveOwner(existing);
300	            }
301	        }
302	    }
303	
304	    /**
305	     * Derives the stable, shared household identifier for a household, formatted {@code HH-<HEX12>}
306	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the normalized
307	     * lastName and address keys. Being a pure function of the household, every owner in it derives
308	     * the same value regardless of creation order.
309	     *
310	     * @param lastNameKey the normalized household lastName key
311	     * @param addressKey  the normalized household address key
312	     * @return the household identifier
313	     */
314	    private String householdId(String lastNameKey, String addressKey) {
315	        try {
316	            byte[] digest = MessageDigest.getInstance("SHA-256")
317	                .digest((lastNameKey + "|" + addressKey).getBytes(StandardCharsets.UTF_8));
318	            StringBuilder hex = new StringBuilder(digest.length * 2);
319	            for (byte b : digest) {
320	                hex.append(String.format("%02x", b));
321	            }
322	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
323	        } catch (NoSuchAlgorithmException ex) {
324	            throw new IllegalStateException("SHA-256 not available", ex);
325	        }
326	    }
327	
328	    /**
329	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
330	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
331	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
332	     * string.
333	     */
334	    private String toHouseholdKey(String value) {
335	        if (value == null) {
336	            return "";
337	        }
338	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
339	    }
340	
341	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
342	    @Override
343	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
344	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
345	        if (currentOwner == null) {
346	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
347	        }
348	        currentOwner.setAddress(ownerFieldsDto.getAddress());
349	        currentOwner.setCity(ownerFieldsDto.getCity());
350	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
351	        currentOwner.setLastName(ownerFieldsDto.getLastName());
352	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
353	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
354	        this.clinicService.saveOwner(currentOwner);
355	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
356	    }
357	
358	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
359	    @Transactional
360	    @Override
361	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
362	        Owner owner = this.clinicService.findOwnerById(ownerId);
363	        if (owner == null) {
364	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
365	        }
366	        this.clinicService.deleteOwner(owner);
367	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
368	    }
369	
370	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
371	    @Override
372	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
373	        Owner owner = this.clinicService.findOwnerById(ownerId);
374	        if (owner == null) {
375	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
376	        }
377	        HttpHeaders headers = new HttpHeaders();
378	        Pet pet = petMapper.toPet(petFieldsDto);
379	        owner.setId(ownerId);
380	        pet.setOwner(owner);
381	        pet.getType().setName(null);
382	        this.clinicService.savePet(pet);
383	        PetDto petDto = petMapper.toPetDto(pet);
384	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
385	            .buildAndExpand(pet.getId()).toUri());
386	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
387	    }
388	
389	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
390	    @Override
391	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
392	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
393	        if (currentOwner != null) {
394	            Pet currentPet = this.clinicService.findPetById(petId);
395	            if (currentPet != null) {
396	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
397	                currentPet.setName(petFieldsDto.getName());
398	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
399	                this.clinicService.savePet(currentPet);
400	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
401	            }
402	        }
403	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
404	    }
405	
406	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
407	    @Override
408	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
409	        HttpHeaders headers = new HttpHeaders();
410	        Visit visit = visitMapper.toVisit(visitFieldsDto);
411	        Pet pet = new Pet();
412	        pet.setId(petId);
413	        visit.setPet(pet);
414	        this.clinicService.saveVisit(visit);
415	        VisitDto visitDto = visitMapper.toVisitDto(visit);
416	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
417	            .buildAndExpand(visit.getId()).toUri());
418	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
419	    }
420	
421	
422	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
423	    @Override
424	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
425	        Owner owner = this.clinicService.findOwnerById(ownerId);
426	        if (owner != null) {
427	            Pet pet = owner.getPet(petId);
428	            if (pet != null) {
429	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
430	            }
431	        }
432	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
433	    }
434	}
